from pprint import pformat
from shlex import split
from subprocess import CalledProcessError, STDOUT, check_output


def _get_command_for_simulator(simulator_name, log_dir):
    # type: (str, str) -> List[str]
    params = "-p" if simulator_name == "cus" else ""
    return split("bash -ce 'cd \"{}\"; /opt/iphy/latest/sosReport.sh {}'".format(log_dir, params))


def collect_sos_report(simulator_name, log_dir, logger):
    # type: (str, str, logging.Logger) -> None
    """
    Collects sos report from given simulator
    :param simulator_name: name of simulator - iphy, cus
    :param log_dir: directory where logs should be stored
    :param logger: logger to be used
    :return:
    """
    logger.debug("Collecting {} sosReport".format(simulator_name))
    cmd = _get_command_for_simulator(simulator_name, log_dir)
    try:
        check_output(cmd, stderr=STDOUT)
        logger.debug("sosReport collected successfully")
    except CalledProcessError as err:
        logger.error(pformat(err.output.decode()))
        logger.error("Failed to execute sosReport.sh script. [{}]".format(err), exc_info=True)
    except OSError as err:
        logger.error(
            "sosReport.sh script does not exist in /opt/iphy/latest/ directory. [{}]".format(err), exc_info=True
        )
